sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var body = request.body.data; // Get data sent by the client

        // Log the incoming body to verify if data is coming correctly
        gs.info('Received request body: ' + JSON.stringify(body));

        var gr = new GlideRecord('u_procurement_form_data'); // Make sure to check the table name

        // Check if a record with the same user_id already exists
        gr.addQuery('u_created_by', body.user_id); // Check for existing user_id
        gr.query();

        if (gr.next()) {
            // Existing record found - Perform update
            gs.info('Record found, updating...');
            gr.setValue('u_procurement_system', body.procurement_system);
            gr.setValue('u_cloud_discovery', body.cloud_discovery);
            gr.setValue('u_third_party_software', body.third_party_software);
            gr.setValue('u_third_party_software_name', body.third_party_software_name);
            gr.setValue('u_client_software', body.client_software);
            gr.setValue('u_integration_type', body.integration_type);

            var updated = gr.update(); // Update the record

            if (updated) {
                gs.info('Record updated successfully with sys_id: ' + gr.sys_id);
                response.setStatus(200);
                response.setBody({ 
                    message: "✅ Data updated successfully!", 
                    sys_id: gr.sys_id 
                });
            } else {
                throw new Error("Update operation failed.");
            }
        } else {
            // No record found - Perform insert
            gs.info('No existing record found, inserting...');
            gr.initialize();
            gr.setValue('u_created_by', body.user_id);
            gr.setValue('u_procurement_system', body.procurement_system);
            gr.setValue('u_cloud_discovery', body.cloud_discovery);
            gr.setValue('u_third_party_software', body.third_party_software);
            gr.setValue('u_third_party_software_name', body.third_party_software_name);
            gr.setValue('u_client_software', body.client_software);
            gr.setValue('u_integration_type', body.integration_type);

            var recordID = gr.insert(); // Insert a new record

            if (recordID) {
                gs.info('Record inserted with sys_id: ' + recordID);
                response.setStatus(201);
                response.setBody({ 
                    message: "✅ Data submitted successfully!", 
                    sys_id: recordID 
                });
            } else {
                throw new Error("Insert operation failed.");
            }
        }
    } catch (err) {
        gs.error('Error: ' + err.message); // Log any error that occurs
        response.setStatus(500);
        response.setBody({ error: "❌ Server error: " + err.message });
    }
})(request, response);
